//! Extended grapheme cluster boundaries (Unicode UAX #29, rules GB1 to GB999),
//! including the Indic conjunct rule GB9c, emoji ZWJ sequences (GB11) and
//! regional indicator pairs (GB12, GB13). Pure Zig; the property tables are
//! generated by `tools/gen_grapheme.py` into `grapheme_data.zig` (`unicode_version`).
//!
//! Everything works on UTF-8 byte offsets and is safe on invalid UTF-8: every
//! invalid byte (a stray continuation byte, a truncated or overlong sequence) is
//! its own cluster, and no function ever returns an offset inside a valid
//! code point. Offsets past the end are clamped to the text length.
//!
//! Boundaries are context dependent (a flag needs the regional indicators before
//! it, a ZWJ sequence the pictograph before the joiner), so `isBoundary` and
//! `prevBoundary` look backwards as far as the rules need; the cost is linear
//! in the length of the cluster at worst, and constant for ordinary text. The exception is a
//! run of regional indicators (flags), where a pair depends on the parity of the whole run:
//! `Iterator`, `count` and `nextBoundaryCarry` carry that parity forward and stay linear, but a
//! call that starts inside such a run (`isBoundary`, `nextBoundary`, `prevBoundary`, `snapDown`
//! at an arbitrary offset) walks back to the start of the run, so costs O(length of the run).
const std = @import("std");
const builtin = @import("builtin");
const data = @import("grapheme_data.zig");

pub const unicode_version = data.unicode_version;

/// Grapheme_Cluster_Break values, in the order of the generated table.
pub const Prop = enum(u4) {
    other,
    cr,
    lf,
    control,
    extend,
    zwj,
    regional_indicator,
    prepend,
    spacing_mark,
    l,
    v,
    t,
    lv,
    lvt,
};

const Info = struct {
    prop: Prop,
    ext_pict: bool,
    /// 0 none, 1 Consonant, 2 Linker, 3 Extend.
    incb: u2,
};

/// Properties of code point `cp`.
fn lookup(cp: u21) Info {
    if (cp < 0x300) {
        // ASCII and Latin-1 fast path: only controls, CR, LF, the soft hyphen (a Control) and the
        // copyright and registered signs (Extended_Pictographic) are not "other".
        if (cp >= 0x20 and cp < 0x7f) return .{ .prop = .other, .ext_pict = false, .incb = 0 };
    }
    var lo: usize = 0;
    var hi: usize = data.starts.len;
    // Greatest index with starts[i] <= cp (starts[0] is 0, so one always exists).
    while (hi - lo > 1) {
        const mid = lo + (hi - lo) / 2;
        if (data.starts[mid] <= cp) lo = mid else hi = mid;
    }
    const v = data.vals[lo];
    return .{ .prop = @enumFromInt(v & 0xF), .ext_pict = v & 0x10 != 0, .incb = @intCast(v >> 5) };
}

/// Whether `cp` is Extended_Pictographic (the emoji-like characters of UAX #29 rule GB11).
pub fn isExtendedPictographic(cp: u21) bool {
    return lookup(cp).ext_pict;
}

const invalid_info: Info = .{ .prop = .control, .ext_pict = false, .incb = 0 };

const Unit = struct { info: Info, len: usize };

fn isCont(b: u8) bool {
    return b & 0xC0 == 0x80;
}

/// The unit (a valid code point, or one invalid byte) that starts at `i < text.len`.
fn unitAt(text: []const u8, i: usize) Unit {
    const n = std.unicode.utf8ByteSequenceLength(text[i]) catch return .{ .info = invalid_info, .len = 1 };
    if (i + n > text.len) return .{ .info = invalid_info, .len = 1 };
    const cp = std.unicode.utf8Decode(text[i..][0..n]) catch return .{ .info = invalid_info, .len = 1 };
    return .{ .info = lookup(cp), .len = n };
}

/// Start of the unit that contains byte `i < text.len`.
fn unitStart(text: []const u8, i: usize) usize {
    if (!isCont(text[i])) return i;
    var s = i;
    var k: usize = 0;
    while (k < 3 and s > 0) : (k += 1) {
        s -= 1;
        if (!isCont(text[s])) {
            const u = unitAt(text, s);
            if (u.len > 1 and s + u.len > i) return s;
            break;
        }
    }
    return i;
}

/// The unit that ends at `end` (> 0): returns its start.
fn unitBeforeStart(text: []const u8, end: usize) usize {
    return unitStart(text, end - 1);
}

/// GB9c context: is there an `InCB=Linker` in the run of `Extend` and `Linker` characters that ends
/// with the unit starting at `a_start`? (Unicode 15.1 to 17 also required a Consonant before the
/// run; the 18.0 test data joins a Linker to a following Consonant whatever comes before it.)
fn linkerBefore(text: []const u8, a_start: usize) bool {
    var s = a_start;
    var seen_linker = false;
    while (true) {
        const info = unitAt(text, s).info;
        switch (info.incb) {
            3 => {},
            2 => seen_linker = true,
            else => return seen_linker,
        }
        if (s == 0) return seen_linker;
        s = unitBeforeStart(text, s);
    }
}

/// GB11 context: is the ZWJ unit starting at `zwj_start` preceded by `ExtPict Extend*`?
fn pictographBefore(text: []const u8, zwj_start: usize) bool {
    var s = zwj_start;
    while (s > 0) {
        s = unitBeforeStart(text, s);
        const info = unitAt(text, s).info;
        if (info.prop == .extend and !info.ext_pict) continue;
        return info.ext_pict;
    }
    return false;
}

/// Units visited by `indicatorsEndingAt`, counted in tests only to bound the work.
pub var test_ri_steps: usize = 0;

/// How many regional indicators end with the unit starting at `a_start` (consecutive).
fn indicatorsEndingAt(text: []const u8, a_start: usize) usize {
    var n: usize = 0;
    var s = a_start;
    while (true) {
        if (builtin.is_test) test_ri_steps += 1;
        if (unitAt(text, s).info.prop != .regional_indicator) return n;
        n += 1;
        if (s == 0) return n;
        s = unitBeforeStart(text, s);
    }
}

/// Whether there is a cluster boundary at byte offset `i`: at 0 and at `text.len` always, never
/// inside a valid code point, and elsewhere as UAX #29 says. Offsets past the end are not
/// boundaries.
pub fn isBoundary(text: []const u8, i: usize) bool {
    if (i == 0 or i == text.len) return true;
    if (i > text.len) return false;
    if (unitStart(text, i) != i) return false;
    return boundaryBetween(text, i, null);
}

/// `isBoundary` for an `i` that is a unit start inside the text. `ri_before` is the number of
/// regional indicators that end just before `i`, when the caller knows it; null: count them.
fn boundaryBetween(text: []const u8, i: usize, ri_before: ?usize) bool {
    const a_start = unitBeforeStart(text, i);
    const a = unitAt(text, a_start).info;
    const b = unitAt(text, i).info;
    const pa = a.prop;
    const pb = b.prop;
    // GB3 to GB5: breaks around controls, except CR LF.
    if (pa == .cr and pb == .lf) return false;
    if (pa == .control or pa == .cr or pa == .lf) return true;
    if (pb == .control or pb == .cr or pb == .lf) return true;
    // GB6 to GB8: Hangul syllable sequences.
    if (pa == .l and (pb == .l or pb == .v or pb == .lv or pb == .lvt)) return false;
    if ((pa == .lv or pa == .v) and (pb == .v or pb == .t)) return false;
    if ((pa == .lvt or pa == .t) and pb == .t) return false;
    // GB9, GB9a, GB9b.
    if (pb == .extend or pb == .zwj or pb == .spacing_mark) return false;
    if (pa == .prepend) return false;
    // GB9c: Indic conjunct (a Linker, then a Consonant).
    if (b.incb == 1 and linkerBefore(text, a_start)) return false;
    // GB11: emoji ZWJ sequence.
    if (pa == .zwj and b.ext_pict and pictographBefore(text, a_start)) return false;
    // GB12, GB13: regional indicator pairs.
    if (pa == .regional_indicator and pb == .regional_indicator) {
        return (ri_before orelse indicatorsEndingAt(text, a_start)) % 2 == 0;
    }
    return true;
}

/// The first boundary after `i`; `text.len` when `i` is at or past the end. If `i` is inside a
/// code point or a cluster this is the end of the cluster that contains it.
pub fn nextBoundary(text: []const u8, i: usize) usize {
    if (i >= text.len) return text.len;
    const p = unitStart(text, i);
    const before = if (p == 0) 0 else indicatorsEndingAt(text, unitBeforeStart(text, p));
    var after: usize = undefined;
    return nextBoundaryCarry(text, p, before, &after);
}

fn extendRun(run: usize, info: Info) usize {
    return if (info.prop == .regional_indicator) run + 1 else 0;
}

/// `nextBoundary` for a caller that walks a string cluster by cluster. `i` must be a cluster
/// boundary, `ri_before` the number of regional indicators that end just before it (0 at the
/// start of the text); `ri_after` receives the same number for the returned boundary, to pass
/// to the next call. Linear on any text, flags included.
pub fn nextBoundaryCarry(text: []const u8, i: usize, ri_before: usize, ri_after: *usize) usize {
    if (i >= text.len) {
        ri_after.* = ri_before;
        return text.len;
    }
    var p = i;
    var run = ri_before;
    while (true) {
        const u = unitAt(text, p);
        run = extendRun(run, u.info);
        p += u.len;
        if (p >= text.len or boundaryBetween(text, p, run)) break;
    }
    ri_after.* = run;
    return p;
}

/// The last boundary before `i` (`i` is clamped to the length); 0 when `i` is 0. If `i` is inside a
/// code point or a cluster this is the start of the cluster that contains it.
pub fn prevBoundary(text: []const u8, i: usize) usize {
    const end = @min(i, text.len);
    if (end == 0) return 0;
    var s = unitBeforeStart(text, end);
    // `k`: regional indicators ending at `s`, once known; a pair then splits by parity, so a run
    // of flags is walked back once, not once per indicator.
    var k: usize = 0;
    while (s > 0) {
        if (k == 0 and unitAt(text, s).info.prop == .regional_indicator) k = indicatorsEndingAt(text, s);
        if (if (k >= 2) k % 2 == 1 else isBoundary(text, s)) return s;
        s = unitBeforeStart(text, s);
        if (k > 0) k -= 1;
    }
    return s;
}

/// Moves `i` back to the start of its cluster (`i` itself when it is a boundary; the length when
/// it is past the end).
pub fn snapDown(text: []const u8, i: usize) usize {
    if (i >= text.len) return text.len;
    return if (isBoundary(text, i)) i else prevBoundary(text, i);
}

/// Iterates the clusters of a string as slices of it.
pub const Iterator = struct {
    text: []const u8,
    /// Always a cluster boundary: start at 0 (or at a boundary with `ri` set to the regional
    /// indicators that end just before it).
    pos: usize = 0,
    ri: usize = 0,

    pub fn next(it: *Iterator) ?[]const u8 {
        if (it.pos >= it.text.len) return null;
        const end = nextBoundaryCarry(it.text, it.pos, it.ri, &it.ri);
        const s = it.text[it.pos..end];
        it.pos = end;
        return s;
    }
};

pub fn iterator(text: []const u8) Iterator {
    return .{ .text = text };
}

/// Number of clusters in `text`.
pub fn count(text: []const u8) usize {
    var it = iterator(text);
    var n: usize = 0;
    while (it.next()) |_| n += 1;
    return n;
}

// ---- tests ------------------------------------------------------------------

const t = std.testing;

fn expectClusters(text: []const u8, want: []const []const u8) !void {
    var it = iterator(text);
    var i: usize = 0;
    while (it.next()) |c| : (i += 1) {
        try t.expect(i < want.len);
        try t.expectEqualStrings(want[i], c);
    }
    try t.expectEqual(want.len, i);
    // Walking back gives the same cut points.
    var p = text.len;
    var k = want.len;
    while (p > 0) {
        k -= 1;
        const q = prevBoundary(text, p);
        try t.expectEqualStrings(want[k], text[q..p]);
        p = q;
    }
}

test "official GraphemeBreakTest.txt" {
    const file = @embedFile("testdata/GraphemeBreakTest.txt");
    var lines = std.mem.splitScalar(u8, file, '\n');
    var buf: std.ArrayList(u8) = .empty;
    defer buf.deinit(t.allocator);
    var marks: std.ArrayList(bool) = .empty; // marks[k]: boundary at byte offset k
    defer marks.deinit(t.allocator);
    var passed: usize = 0;
    var total: usize = 0;
    while (lines.next()) |raw| {
        // The file may be checked out with CRLF line endings.
        const line = std.mem.trimEnd(u8, raw, "\r");
        if (line.len == 0 or line[0] == '#') continue;
        buf.clearRetainingCapacity();
        marks.clearRetainingCapacity();
        var toks = std.mem.tokenizeAny(u8, line, " \t");
        var pending: ?bool = null;
        while (toks.next()) |tok| {
            if (std.mem.eql(u8, tok, "\u{f7}")) {
                pending = true;
            } else if (std.mem.eql(u8, tok, "\u{d7}")) {
                pending = false;
            } else {
                const cp = try std.fmt.parseInt(u21, tok, 16);
                try marks.append(t.allocator, pending.?);
                var enc: [4]u8 = undefined;
                const n = try std.unicode.utf8Encode(cp, &enc);
                try buf.appendSlice(t.allocator, enc[0..n]);
                var k: usize = 1;
                while (k < n) : (k += 1) try marks.append(t.allocator, false);
            }
        }
        try marks.append(t.allocator, true); // the end
        const text = buf.items;
        total += 1;
        var ok = true;
        // Per-offset check, and the forward and backward walks.
        for (marks.items, 0..) |want, off| {
            if (isBoundary(text, off) != want) ok = false;
        }
        var p: usize = 0;
        while (p < text.len) {
            const nb = nextBoundary(text, p);
            if (!marks.items[nb] or nb <= p) ok = false;
            p = nb;
        }
        p = text.len;
        while (p > 0) {
            const pb = prevBoundary(text, p);
            if (!marks.items[pb] or pb >= p) ok = false;
            p = pb;
        }
        if (ok) passed += 1 else std.debug.print("grapheme test failed: {s}\n", .{line});
    }
    try t.expect(total > 800);
    try t.expectEqual(total, passed);
}

test "combining marks, emoji, flags, Hangul" {
    try expectClusters("cafe\u{301}!", &.{ "c", "a", "f", "e\u{301}", "!" });
    try expectClusters("\u{1F469}\u{200D}\u{1F469}\u{200D}\u{1F467}x", &.{ "\u{1F469}\u{200D}\u{1F469}\u{200D}\u{1F467}", "x" });
    try expectClusters("\u{1F44D}\u{1F3FD}a", &.{ "\u{1F44D}\u{1F3FD}", "a" });
    // Three flags: pairs.
    try expectClusters("\u{1F1F3}\u{1F1EC}\u{1F1EB}\u{1F1F7}\u{1F1E9}", &.{ "\u{1F1F3}\u{1F1EC}", "\u{1F1EB}\u{1F1F7}", "\u{1F1E9}" });
    // Hangul jamo L V T compose into one cluster.
    try expectClusters("\u{1112}\u{1161}\u{11AB}a", &.{ "\u{1112}\u{1161}\u{11AB}", "a" });
    try expectClusters("\r\n\n", &.{ "\r\n", "\n" });
    // Devanagari conjunct (GB9c): KA VIRAMA SSA is one cluster.
    try expectClusters("\u{0915}\u{094D}\u{0937}x", &.{ "\u{0915}\u{094D}\u{0937}", "x" });
}

test "invalid UTF-8: each invalid byte is its own cluster, never inside a code point" {
    try expectClusters("a\x80b", &.{ "a", "\x80", "b" });
    try expectClusters("\xE2\x82", &.{ "\xE2", "\x82" }); // truncated 3-byte sequence
    try expectClusters("\xff\xfe", &.{ "\xff", "\xfe" });
    try expectClusters("\xC0\x80", &.{ "\xC0", "\x80" }); // overlong
    try expectClusters("e\xCC\x81\x80", &.{ "e\xCC\x81", "\x80" });
    const s = "x\u{1F469}\u{200D}\u{1F467}\xE2\x82\xAC\x80";
    var i: usize = 0;
    while (i <= s.len + 2) : (i += 1) {
        const nb = nextBoundary(s, i);
        const pb = prevBoundary(s, i);
        try t.expect(nb <= s.len and pb <= s.len);
        try t.expect(isBoundary(s, nb) and isBoundary(s, pb));
        try t.expect(snapDown(s, i) <= @min(i, s.len));
    }
    try t.expect(!isBoundary("\u{e9}", 1)); // inside a code point
    try t.expect(!isBoundary("ab", 3));
}

test "offsets are clamped and mid-cluster positions resolve to the cluster" {
    const s = "e\u{301}x";
    try t.expectEqual(@as(usize, 0), prevBoundary(s, 0));
    try t.expectEqual(@as(usize, 3), nextBoundary(s, 0));
    try t.expectEqual(@as(usize, 3), nextBoundary(s, 1));
    try t.expectEqual(@as(usize, 0), prevBoundary(s, 2));
    try t.expectEqual(@as(usize, 0), snapDown(s, 1));
    try t.expectEqual(@as(usize, 3), snapDown(s, 3));
    try t.expectEqual(s.len, nextBoundary(s, 99));
    try t.expectEqual(s.len, snapDown(s, 99));
}

test "a long cluster is handled in linear time" {
    var buf: [4000]u8 = undefined;
    @memcpy(buf[0..1], "a");
    var n: usize = 1;
    while (n + 2 <= buf.len) : (n += 2) @memcpy(buf[n..][0..2], "\u{301}");
    try t.expectEqual(n, nextBoundary(buf[0..n], 0));
    try t.expectEqual(@as(usize, 0), prevBoundary(buf[0..n], n));
}

/// `n` copies of the flag of Nigeria's first regional indicator, in memory the test frees.
fn flags(n: usize) ![]u8 {
    const buf = try t.allocator.alloc(u8, n * 4);
    for (0..n) |i| @memcpy(buf[i * 4 ..][0..4], "\u{1F1F3}");
    return buf;
}

test "a long run of regional indicators is walked in linear time" {
    const run = try flags(4000);
    defer t.allocator.free(run);
    test_ri_steps = 0;
    try t.expectEqual(@as(usize, 2000), count(run));
    try t.expect(test_ri_steps < 4 * 4000);
    // One step back from the end walks the run once, not once per indicator.
    test_ri_steps = 0;
    try t.expectEqual(run.len - 8, prevBoundary(run, run.len));
    try t.expectEqual(run.len - 8, prevBoundary(run, run.len - 3));
    try t.expect(test_ri_steps < 4 * 4000);
    // An odd run ends with a lone indicator; the carried parity and the random-access answer agree.
    const odd = try flags(5);
    defer t.allocator.free(odd);
    try t.expectEqual(@as(usize, 3), count(odd));
    var it = iterator(odd);
    var at: usize = 0;
    while (it.next()) |cl| : (at += cl.len) try t.expect(isBoundary(odd, at));
    try t.expectEqual(@as(usize, 16), prevBoundary(odd, odd.len));
    try t.expectEqual(@as(usize, 8), nextBoundary(odd, 4));
    try t.expectEqual(@as(usize, 16), nextBoundary(odd, 9));
}
